using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using MemeManager;

static class GroupingTests {
 static int checks;static void Check(bool value,string message){if(!value)throw new Exception("FAIL: "+message);Console.WriteLine("PASS: "+message);checks++;}
 public static int Run(string root){string legacyRoot=Path.Combine(root,"legacy-groups");Directory.CreateDirectory(legacyRoot);
  File.WriteAllText(Path.Combine(legacyRoot,"library.json"),"{\"Memes\":[{\"Id\":\"legacy\",\"Name\":\"旧图片\",\"Extension\":\".png\",\"GroupId\":\"a\"}],\"Groups\":[{\"Id\":\"a\",\"Name\":\"旧分组\"},{\"Id\":\"b\",\"Name\":\"新分组\"}],\"Settings\":{}}");
  var legacy=new Library(legacyRoot);var item=legacy.Data.Memes.Single();Check(item.GroupIds.SequenceEqual(new[]{"a"}),"legacy single-group metadata migrates without losing membership");Grouping.Add(item,"b");Grouping.Add(item,"b");legacy.Save();var again=new Library(legacyRoot);Check(again.Data.Memes[0].GroupIds.SequenceEqual(new[]{"a","b"})&&again.Data.Memes.Count==1,"multiple memberships persist without duplicate image records");Grouping.Remove(item,"a");Check(item.GroupIds.SequenceEqual(new[]{"b"}),"removing one membership preserves other groups");Grouping.Set(item,new string[0]);Check(!Grouping.IsGrouped(item)&&item.GroupId==null,"clearing every membership makes image ungrouped");
  string orderRoot=Path.Combine(root,"json-order");Directory.CreateDirectory(orderRoot);File.WriteAllText(Path.Combine(orderRoot,"library.json"),"{\"Memes\":[{\"Id\":\"x\",\"GroupIds\":[\"a\",\"b\"],\"GroupId\":\"a\"},{\"Id\":\"y\",\"GroupId\":\"a\",\"GroupIds\":[]}],\"Groups\":[{\"Id\":\"a\",\"Name\":\"A\"},{\"Id\":\"b\",\"Name\":\"B\"}],\"Settings\":{}}");var reordered=new Library(orderRoot);Check(reordered.Data.Memes[0].GroupIds.Count==2&&!Grouping.IsGrouped(reordered.Data.Memes[1]),"explicit membership lists win over legacy fields in either JSON order");
  var db=new Database();db.Groups.AddRange(new[]{new Group{Id="root",Name="日常"},new Group{Id="child",Name="动物",ParentId="root"},new Group{Id="leaf",Name="猫",ParentId="child"},new Group{Id="other",Name="动物"}});var nested=new Meme{Id="one",GroupIds=new List<string>{"child","leaf","other"}};db.Memes.Add(nested);
  Check(Grouping.Path(db.Groups,"leaf")=="日常 / 动物 / 猫"&&Grouping.Rows(db.Groups).Select(x=>x.Group.Id).SequenceEqual(new[]{"root","child","leaf","other"}),"nested group paths and sidebar order preserve hierarchy");var branch=Grouping.Branch(db.Groups,"root");Check(branch.SetEquals(new[]{"root","child","leaf"})&&db.Memes.Count(x=>Grouping.Matches(x,branch))==1,"parent view aggregates descendants without counting multi-group images twice");bool cycle=false;try{Grouping.SetParent(db.Groups,db.Groups[0],"leaf");}catch(InvalidOperationException){cycle=true;}Check(cycle&&db.Groups[0].ParentId==null,"moving a parent into its descendant is rejected");Grouping.SetParent(db.Groups,db.Groups[2],"other");Check(Grouping.Path(db.Groups,"leaf")=="动物 / 猫","existing groups can move under a different parent");
  db.Groups.Add(new Group{Id="broken",Name="异常",ParentId="missing"});db.Groups.Add(new Group{Id="cycle-a",Name="循环 A",ParentId="cycle-b"});db.Groups.Add(new Group{Id="cycle-b",Name="循环 B",ParentId="cycle-a"});Grouping.Set(nested,nested.GroupIds.Concat(new[]{"gone"}));Grouping.Normalize(db);Check(db.Groups.Single(x=>x.Id=="broken").ParentId==null&&Grouping.Rows(db.Groups).Count()==db.Groups.Count&&!nested.GroupIds.Contains("gone"),"invalid old hierarchy and missing memberships normalize safely");
  Grouping.SetParent(db.Groups,db.Groups.Single(x=>x.Id=="leaf"),"child");Grouping.Add(nested,"root");Grouping.DeleteNode(db,db.Groups.Single(x=>x.Id=="child"));Check(db.Groups.Single(x=>x.Id=="leaf").ParentId=="root"&&nested.GroupIds.Contains("leaf")&&nested.GroupIds.Contains("other")&&!nested.GroupIds.Contains("child")&&db.Memes.Count==1,"deleting one group promotes children and preserves image and other memberships");
  return checks;
 }
}
